 const breathe=Math.sin(s*1.65)*(breathing?12:3.5);
 const chestScale=breathing?.018*(1+Math.sin((s-en('aire'))*1.65)):0;
 const open=ramp(s,en('desperté'),en('pedirlo'));
 const blink=closed?0.08:(s%4.7<0.13?0.12:Math.max(.13,open));
 return <g>
  <ellipse cy="6" rx="160" ry="25" fill="#151e28" opacity=".22"/>
  {seated?<><path d="M-57-255Q-90-165-106-145L-110-18M50-255Q100-180 104-145L112-18" fill="none" stroke="#344253" strokeWidth="59" strokeLinecap="round"/><path d="M-138-12h65M85-12h67" stroke="#24292e" strokeWidth="30" strokeLinecap="round"/></>:<><path d={`M-43-256L${-48+Math.sin(s*2)*8}-22M43-256L${48-Math.sin(s*2)*8}-22`} stroke="#344253" strokeWidth="54" strokeLinecap="round"/><path d="M-76-13h58M20-13h60" stroke="#24292e" strokeWidth="28" strokeLinecap="round"/></>}
