   <ellipse cx="-67" cy="-554" rx="12" ry="20" fill="#ae7351"/><ellipse cx="67" cy="-554" rx="12" ry="20" fill="#ae7351"/>
   <path d="M-66-573Q-77-644-10-649Q66-650 68-582L52-601Q15-621-28-606L-53-579Z" fill="#323038"/>
