   <path d="M-45-576Q-29-588-13-578M13-578Q28-588 43-577" stroke="#493329" strokeWidth="6" fill="none" strokeLinecap="round"/>
   {[-28,28].map(x=><g key={x} transform={`translate(${x} -560) scale(1 ${blink})`}><ellipse rx="9" ry="11" fill="#171c23"/><circle cx="3" cy="-4" r="3" fill="#fff8e7"/></g>)}
   <path d="M0-556Q12-537 2-533" fill="none" stroke="#94573e" strokeWidth="5" strokeLinecap="round"/>
