export const Escena:React.FC=()=>{
 const {s}=useS();
 const water=en('agua'),back=en('palabra'),out=en('Ahora');
 // Last repeated gratitude restores the exact opening camera and room, now in morning gold.
 const finale=en('respiro');
 const gold=ramp(s,0,DUR*.8);
 const layers=[{a:0,b:water,draw:<Bedroom s={s} gold={gold}/>},{a:water,b:back,draw:<Kitchen s={s} gold={gold}/>},{a:back,b:out,draw:<Bedroom s={s} gold={gold} prayer/>},{a:out,b:finale,draw:<Street s={s}/>},{a:finale,b:DUR+2,draw:<Bedroom s={s} gold={1} final/>}];
 return <AbsoluteFill style={{background:'#3f4b5a'}}><svg width="1080" height="1920" viewBox="0 0 1080 1920">
  <defs>
   <linearGradient id={`wall-${Math.round(s*30)}`} x2="1" y2="1"><stop stopColor={blend('#596674','#bfae8d',gold)}/><stop offset="1" stopColor={blend('#8b9698','#ddc7a0',gold)}/></linearGradient>
   <linearGradient id={`sky-${Math.round(s*30)}`} x2="0" y2="1"><stop stopColor={blend('#526c87','#9eabb3',gold)}/><stop offset="1" stopColor={blend('#c8b5a2','#f3c191',gold)}/></linearGradient>
   <linearGradient id="skin"><stop stopColor="#dba777"/><stop offset=".55" stopColor="#bd865d"/><stop offset="1" stopColor="#9b6448"/></linearGradient>
   <linearGradient id="shirt"><stop stopColor="#a5a8a4"/><stop offset=".65" stopColor="#838b8c"/><stop offset="1" stopColor="#68747b"/></linearGradient>
   <linearGradient id="linen" x2="0" y2="1"><stop stopColor="#e1dbca"/><stop offset="1" stopColor="#b8bbad"/></linearGradient>
   <radialGradient id="glow"><stop stopColor="#ffe2a0" stopOpacity=".85"/><stop offset="1" stopColor="#ffe2a0" stopOpacity="0"/></radialGradient>
   <radialGradient id="vignette"><stop offset=".5" stopColor="#15242b" stopOpacity="0"/><stop offset="1" stopColor="#15242b" stopOpacity=".30"/></radialGradient>
  </defs>
  <g transform={`translate(${Math.sin(s*.19)*7} ${Math.sin(s*.15)*5}) translate(540 1000) scale(${1+.035*s/DUR+.005*Math.sin(s*.4)}) translate(-540 -1000)`}>
   {layers.map((l,i)=><g key={i} opacity={i===0?1:ramp(s,l.a-.5,l.a+.5)}>{s>=l.a-.5&&s<=l.b+.5?l.draw:null}</g>)}
   <path d={`M1020 420L${270+Math.sin(s*.2)*40} 1700H640L1030 640Z`} fill="#ffe4ac" opacity={.04+gold*.035}/>
   {Array.from({length:40},(_,i)=><circle key={i} cx={(i*167+Math.sin(s*.27+i)*19)%1080} cy={420+((i*119-s*(7+i%4))%1300+1300)%1300} r={1.7+i%3} fill="#ffe7b4" opacity={.13+.19*(.5+.5*Math.sin(s*.8+i))}/>)}
  </g>
  <rect width="1080" height="1920" fill="url(#vignette)"/>
 </svg></AbsoluteFill>;
};
